import { Component, inject, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { MoneyPipe } from '../currencies/money.pipe';
import { DashboardService } from './dashboard.service';

// The revenue billed over a chosen date range (over all time until a range is chosen): the total of the invoices
// issued within it that were sent (drafts and cancelled invoices are left out), in the home currency, broken down
// by job so the highest-earning jobs show first.
@Component({
  selector: 'app-revenue-report',
  imports: [MoneyPipe],
  styles: `
    .revenue-report-range {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.5rem;
    }
    .revenue-report-figures {
      display: grid;
      grid-template-columns: max-content max-content;
      gap: 0.25rem 1.5rem;
    }
    .revenue-report-figures dd {
      margin: 0;
      text-align: right;
    }
    .revenue-report-jobs th,
    .revenue-report-jobs td {
      padding: 0.25rem 0.75rem;
      text-align: left;
    }
    .revenue-report-jobs .amount {
      text-align: right;
    }
  `,
  template: `
    <section aria-labelledby="revenue-report-heading" data-testid="revenue-report">
      <h2 id="revenue-report-heading">Revenue report</h2>
      <form class="revenue-report-range" (submit)="apply($event, fromInput.value, toInput.value)">
        <label for="revenue-report-from">From</label>
        <input #fromInput id="revenue-report-from" type="date" required data-testid="revenue-report-from" />
        <label for="revenue-report-to">To</label>
        <input #toInput id="revenue-report-to" type="date" required data-testid="revenue-report-to" />
        <button type="submit" data-testid="revenue-report-apply">Show revenue</button>
      </form>
      @if (rangeError()) {
        <p role="alert" data-testid="revenue-report-range-error">{{ rangeError() }}</p>
      } @else if (report.error()) {
        <p role="alert" data-testid="revenue-report-error">Could not load the revenue report.</p>
      } @else if (report.value(); as r) {
        <p data-testid="revenue-report-period">
          @if (r.from && r.to) {
            From {{ r.from }} to {{ r.to }}
          } @else {
            All time
          }
        </p>
        <dl class="revenue-report-figures" aria-live="polite">
          <dt>Invoices</dt>
          <dd data-testid="revenue-report-invoices">{{ r.invoices }}</dd>
          <dt>Total billed</dt>
          <dd data-testid="revenue-report-total">{{ r.total | money: r.homeCurrency }}</dd>
        </dl>
        <h3 id="revenue-by-job-heading">Revenue by job</h3>
        @if (r.jobs.length) {
          <table class="revenue-report-jobs" aria-labelledby="revenue-by-job-heading" data-testid="revenue-jobs">
            <thead>
              <tr>
                <th scope="col">Job</th>
                <th scope="col">Client</th>
                <th scope="col" class="amount">Invoices</th>
                <th scope="col" class="amount">Revenue</th>
              </tr>
            </thead>
            <tbody>
              @for (job of r.jobs; track job.projectId) {
                <tr [attr.data-testid]="'revenue-job-row-' + job.projectId">
                  <th scope="row" data-testid="revenue-job-name">{{ job.projectName }}</th>
                  <td data-testid="revenue-job-client">{{ job.clientName }}</td>
                  <td class="amount" data-testid="revenue-job-invoices">{{ job.invoices }}</td>
                  <td class="amount" data-testid="revenue-job-amount">{{ job.amount | money: r.homeCurrency }}</td>
                </tr>
              }
            </tbody>
          </table>
        } @else {
          <p data-testid="revenue-jobs-empty">No revenue billed in this period.</p>
        }
      }
    </section>
  `,
})
export class RevenueReport {
  private readonly service = inject(DashboardService);

  /** The chosen date range; until one is chosen the report covers all time. */
  private readonly range = signal<{ from: string; to: string } | null>(null);
  protected readonly rangeError = signal<string | null>(null);

  protected readonly report = rxResource({
    params: () => ({ range: this.range() }),
    stream: ({ params }) => this.service.revenueReport(params.range ?? undefined),
  });

  protected apply(event: Event, from: string, to: string): void {
    event.preventDefault();
    if (!from || !to) {
      return;
    }
    if (from > to) {
      this.rangeError.set('The start date must not be after the end date.');
      return;
    }
    this.rangeError.set(null);
    this.range.set({ from, to });
  }
}
import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { CurrencyCode } from '../clients/client.service';

export interface TopClient {
  id: number;
  name: string;
  /** The client's currency; what they owe is in it. */
  currency: CurrencyCode;
  outstanding: number;
  /** What they owe converted into the home currency; the clients are ranked by it. */
  outstandingHome: number;
}

/** What is still owed in one currency; different currencies are never added together. */
export interface CurrencyTotal {
  currency: CurrencyCode;
  amount: number;
}

/** What is overdue, in the home currency, by how many days past due. */
export interface OverdueBuckets {
  days0To30: number;
  days31To60: number;
  days60Plus: number;
}

export interface DashboardSummary {
  clients: number;
  projects: number;
  /** What is still owed, one total per currency anything is owed in. */
  outstanding: CurrencyTotal[];
  /** Everything outstanding as one total in the home currency, each invoice converted at its issue date's rate. */
  outstandingHome: number;
  overdue: number;
  /** The currency the overdue amount is given in. */
  homeCurrency: CurrencyCode;
  /** What is left to pay on overdue invoices plus the late fees and instalment interest they have built up, in the home currency. */
  overdueAmount: number;
  /** The overdue amount split by how many days past due each invoice is. */
  overdueBuckets: OverdueBuckets;
  topClients: TopClient[];
  /** How many tasks not yet done are past their due date. */
  overdueTasks: number;
}

/** The tax charged on invoices issued on or between two dates, in the home currency. */
export interface TaxSummary {
  from: string;
  to: string;
  homeCurrency: CurrencyCode;
  /** How many invoices the tax came from. */
  invoices: number;
  tax: number;
  /** The levy (second tax). */
  levy: number;
  /** The tax and levy together. */
  total: number;
}

/** The revenue billed for one job (project), in the home currency. */
export interface JobRevenue {
  projectId: number;
  projectName: string;
  clientName: string;
  /** How many invoices the job's revenue came from. */
  invoices: number;
  amount: number;
}

/**
 * The revenue billed on invoices issued on or between two dates (over all time when the dates are null), in the
 * home currency, broken down by job with the highest-earning job first.
 */
export interface RevenueReport {
  from: string | null;
  to: string | null;
  homeCurrency: CurrencyCode;
  /** How many invoices the revenue came from. */
  invoices: number;
  total: number;
  jobs: JobRevenue[];
}

/** One instalment expected in, in its invoice's currency. */
export interface ForecastEntry {
  id: number;
  date: string;
  amount: number;
  currency: CurrencyCode;
  invoiceId: number;
  projectId: number;
  projectName: string;
  clientName: string;
}

/** The money expected in from instalments still to be paid, earliest due first, with the total in the home currency. */
export interface Forecast {
  homeCurrency: CurrencyCode;
  entries: ForecastEntry[];
  total: number;
}

@Injectable({ providedIn: 'root' })
export class DashboardService {
  private readonly http = inject(HttpClient);

  summary(): Observable<DashboardSummary> {
    return this.http.get<DashboardSummary>('/api/dashboard');
  }

  taxSummary(from: string, to: string): Observable<TaxSummary> {
    return this.http.get<TaxSummary>('/api/dashboard/tax-summary', { params: new HttpParams().set('from', from).set('to', to) });
  }

  /** The revenue report over the given range, or over all time when no range is given. */
  revenueReport(range?: { from: string; to: string }): Observable<RevenueReport> {
    const params = range ? new HttpParams().set('from', range.from).set('to', range.to) : new HttpParams();
    return this.http.get<RevenueReport>('/api/dashboard/revenue-report', { params });
  }

  forecast(): Observable<Forecast> {
    return this.http.get<Forecast>('/api/dashboard/forecast');
  }
}
